		UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
			goodsId        = self._cellData.icon,
			goodsNum       = self._cellData.num,
			prices         = self._cellData.prices,
			coinPrices     = self._cellData.coinPrices,
			maxBuyNum      = self._cellData.currentStock,
			rewards        = self._cellData.rewards,
			remainTime     = self._cellData.refreshTime,
			endTime        = self._cellData.nextRefreshLeftSeconds,
			refreshType    = self._cellData.refreshType,
			payPoint       = self._cellData.price,
			buyCb          = function (price, buyNum)
				self:OnBuyItem(self._cellData.productId, price, buyNum)
			end
		}})
	end
	
end
