---刷新cell状态
function RegressionNewGiftBagCell:RefreshCellState()
	local isSoldOut = self._cellData.currentStock == 0
	
	local isGray = isSoldOut or false
	KTool.SetActive(self.DisableMask, isGray)
	KTool.SetActive(self.FinishGroup, isSoldOut)

end

function RegressionNewGiftBagCell:RefreshStock()
	-- 库存
	if checkNumber(self._cellData.stock) == -1 then
		KTool.SetActive(self.GroupDesc2, false)
	else
		KTool.SetActive(self.GroupDesc2, true)
		CfUtils.FillText(self.TxtNumber, self._cellData.currentStock)
	end
end

