---刷新价格
function RegressionNewGiftBagCell:RefreshPrice(data)
	local isFree = self:ProductIsFree(data)
	KTool.SetActive(self.PriceGroup, not isFree)
	KTool.SetActive(self.FreeGroup, isFree)
	
	local node = self.controller.transform:Find('BtnNode/GiftPackQuality')
	if isFree then
		CfUtils.SetUISwitchImage(node, 1)
		return
	else
		CfUtils.SetUISwitchImage(node, 2)
	end
	
	local curPriceTxt = self.CurPrice:Find('TextNumber')
	if isNotNull(data.payPoint) then
		-- 货币购买
		CfUtils.SetActive(self.CurPrice, true)
		CfUtils.SetActive(self.CurPriceIcon, false)
		local windowPricesId = CfUtils.GetWindowsPriceId(data)
		CfUtils.FillText(curPriceTxt, CfUtils.GetCustomDisplayPrice(windowPricesId, data.channelProductId, 24))
		if checkInt(data.original) > 0 then
			CfUtils.SetActive(self.OriPrice, true)
			CfUtils.FillText(self.OriPriceTxt, CfUtils.GetDisplayPrice(data.original))
			CfUtils.SetActive(self.OriPriceIcon, false)
		else
			CfUtils.SetActive(self.OriPrice, false)
		end
		return
	end
	
	if not data.prices then return end
	
	local currencyVo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(data.prices[1].currency))
	KTool.SetActive(self.CurPrice, true)
	CfUtils.SetActive(self.CurPriceIcon, true)
	CfUtils.FillImage(self.CurPriceIcon, currencyVo.photoPath)
	CfUtils.FillText(curPriceTxt, data.prices[1].current)
	if checkInt(data.prices[1].original) == 0 then
		KTool.SetActive(self.OriPrice, false)
	else
		KTool.SetActive(self.OriPrice, true)
		CfUtils.FillText(self.OriPriceTxt, data.prices[1].original)
		CfUtils.FillImage(self.OriPriceIcon, currencyVo.photoPath)
		CfUtils.SetActive(self.OriPriceIcon, true)
	end
end

function RegressionNewGiftBagCell:ProductIsFree(product)
	if product.prices and table.count(product.prices) > 0 then
		for i = 1, #product.prices do
			if product.prices[i].current ~= 0 then
				return false
			end
		end
		return true
	end
	
	return checkInt(product.isFree) == 1
end

---刷新奖励预览
function RegressionNewGiftBagCell:RefreshRewards(data)
	-----@type CommonGoodsListLight
	local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight, OverseaStoreConstants.ScrPath.CommonGoodsListLight)
	local rewards = clone(data.rewards)
	if #rewards > 3 then
		for  i = #rewards, 4, -1 do
			table.remove(rewards, i)
		end
	end
	scr:FreshBaseUI(rewards)
end

function RegressionNewGiftBagCell:OnBuyItem(productId, price, buyNum)
	local isFree = self:ProductIsFree(self._cellData)
	if isFree then
		self:OnFreeBuy(productId)
	else
		self:OnBuy(productId, price, buyNum)
	end
end

function RegressionNewGiftBagCell:OnFreeBuy(productId)
	GameUtils.Request(Interfaces.NewRegressShopFreeBuy,{productId = productId},function(request, response)
		if checkNumber(response.errCode) == 0 then
			local responseData = response.data
			if table.count(responseData.rewards) > 0 then
				GoodsUtils.DrawRewards(responseData.rewards,true)
				CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
			end
			self:RefreshShow()
		end
	end)
end

function RegressionNewGiftBagCell:RefreshShow(buyNum)
	local buyNum = isNotNull(buyNum) and buyNum or 1
	if self._cellData.currentStock > 0 then
		self._cellData.currentStock = self._cellData.currentStock - buyNum
	end
	self:RefreshCellState()
	self:RefreshStock()
	---@type RegressionUtils
	local RegressionUtils = import('Game.Activity.RegressionActivity.RegressionUtils')
	RegressionUtils.RefreshRedPoint(self.type)
end

function RegressionNewGiftBagCell:OnBuy(productId, price, buyNum)
	local price = self._cellData.price
	if checkNumber(price) > 0 then
		SDKService:GetInstance():PayMoney({
			productId = self._cellData.productId,
			channelProductId = self._cellData.channelProductId,
			productDesc = self._cellData.price .. localize("回归礼包"),
			payAmount = checkNumber(self._cellData.price),
			data = self._cellData
		})
		return
	end
	
	local price = self._cellData.prices[1]
	local requestPath = Interfaces.NewRegressShopBuy
	local data = {
		productId = productId,
		num       = buyNum,
		currency =  price.currency,
	}
	GameUtils.Request(requestPath, data, function(request, response)
		if checkNumber(response.errCode) == 0 then
			local responseData = checkTable(response.data)
			if #responseData.rewards > 0 then
				local consume = {}
				
				table.insert(consume, { ["num"] = -price.current * buyNum;
										["goodsId"] = price.currency; })
				GoodsUtils.DrawRewards(consume)
				GoodsUtils.DrawRewards(responseData.rewards,true)
				UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
				
				self:RefreshShow(buyNum)
			end
		end
	end, function(errStr)
		if string.isEmpty(errStr) or errStr == nil then
			return
		end
		printError("store buy" .. errStr)
	end)
end

function RegressionNewGiftBagCell:OnEventSdkEvent(parameters)
	--- sdk pay succeed
	if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
		self:RefreshShow()
	end
end

--endregion private

return RegressionNewGiftBagCell